{
  "technical_and_design_decisions": [
    "Target platform is the Spring XD runtime; new load-testing capabilities are implemented as XD modules (source and sink) based on Spring Integration, packaged and registered via the standard XD module registry.",
    "Java 17 is used as the language/JDK baseline, consistent with the Spring Framework 6.0 baseline stated in the specification.",
    "U1 AMI is built on AWS EC2 using Packer with a shell provisioning script; the image includes the JDK, Apache Kafka distribution (broker + ZooKeeper), the Kafka perf-test harness, and basic monitoring tools, and is validated by launching an instance and running a smoke perf test.",
    "U2 load generator is a 'source' module with configurable options: message payload size, messages-per-second rate, total message count, and configurable headers so downstream measurement is possible.",
    "U3 load receiving 'sink' module measures received throughput by counting messages and bytes per reporting interval and publishing metrics through XD's metrics facilities; results are logged and exposed via the XD admin REST endpoint.",
    "U4 Windows CI is implemented as additional CI jobs (Jenkins/Concourse on EC2 Windows AMIs); the story scope is limited to build scheduling, AMI experimentation, and isolation/triage of failing tests, not fixing every failing test.",
    "U5 Kafka source offset fix uses the Kafka consumer API with explicit offset seek/commit handling so fetches can start from caller-supplied offsets; compatibility with existing XD Kafka module options is preserved.",
    "U6 benchmark uses a simple stream composed of the U2 source and U3 sink communicating over the Kafka message bus, executed on the U1 AMI; throughput is characterized as end-to-end messages/second and MB/second across a small matrix of payload sizes and rates.",
    "U7 collateral site is a static GitHub Pages site generated with Jekyll, with dedicated sections for samples, tutorials, links, performance benchmarks, and reference architectures.",
    "U8 Lattice/Diego POC deploys XD runtime containers as Lattice/Diego workloads (LRPs) via the receptor API and produces a written SPI design, scope assessment, and risk register as its primary deliverables.",
    "All work is performed by a single developer; effort is estimated as net development workdays (8 hours each), excluding calendar waiting time (e.g., CI queue time, AMI build wall-clock time, POC observation time)."
  ],
  "assumptions": [
    "An AWS account with permissions to create AMIs and launch EC2 instances is available.",
    "The existing XD code base, including the current Kafka source module, is available and builds cleanly at the start of the increment.",
    "A Kafka cluster for development/integration testing is provisioned as part of the U1 AMI work; no separate cluster procurement is required.",
    "CI infrastructure (Jenkins/Concourse master) already exists; only Windows workers/jobs and Windows AMIs need to be added.",
    "For U4, actual fixes to the isolated failing Windows tests are out of scope; the deliverable is a stable CI setup plus a triaged, documented list of remaining failures.",
    "A GitHub repository with gh-pages enabled exists for U7; content sources (existing samples, tutorials, benchmark data) are accessible.",
    "Lattice/Diego source and documentation are publicly available; a small test environment can be built on EC2 for the POC.",
    "Code review, rework, and routine unit testing effort are included within each activity estimate.",
    "Dependencies between stories follow the natural order (U1 before U6; U2/U3 before U6), but since estimates are effort-based, ordering does not change the totals.",
    "No external team approvals, procurement delays, or extended environment downtime are included in the estimates."
  ],
  "activities": [
    {
      "activity_id": "A1.1",
      "activity_name": "Define AMI requirements and package list (U1)",
      "activity_description": "Identify required OS packages and tools for Kafka performance testing (JDK, Kafka distribution, perf-test harness, monitoring utilities); select base EC2 AMI; record versions.",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "A1.2",
      "activity_name": "Author AMI provisioning scripts (U1)",
      "activity_description": "Write Packer template and shell provisioning scripts that install and configure Kafka, ZooKeeper, and the perf-test tooling on the base image.",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "A1.3",
      "activity_name": "Build and validate AMI (U1)",
      "activity_description": "Build the AMI, launch a test EC2 instance, start Kafka, and run a smoke performance test to validate the image end to end.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A1.4",
      "activity_name": "Document and publish AMI (U1)",
      "activity_description": "Write usage documentation (AMI ID, launch instructions, perf-test invocation) and share the AMI with the team.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A2.1",
      "activity_name": "Design load generator source module (U2)",
      "activity_description": "Define module options (payload size, rate, message count, headers) and the message-generation strategy consistent with the XD module model.",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "A2.2",
      "activity_name": "Implement load generator source module (U2)",
      "activity_description": "Implement the source module code and module descriptor/configuration so it can be registered and deployed in an XD stream.",
      "most_likely_effort": 3.0
    },
    {
      "activity_id": "A2.3",
      "activity_name": "Unit test load generator (U2)",
      "activity_description": "Write unit tests covering payload generation, rate limiting, option parsing, and boundary conditions.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A2.4",
      "activity_name": "Integration test and document load generator (U2)",
      "activity_description": "Deploy the module in a local XD runtime, verify stream deployment and emission behavior, and write user-facing module documentation.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A3.1",
      "activity_name": "Design load receiving sink module (U3)",
      "activity_description": "Define the measurement approach: message/byte counters, reporting interval, and how throughput metrics are exposed via XD metrics and logs.",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "A3.2",
      "activity_name": "Implement load receiving sink module (U3)",
      "activity_description": "Implement the sink module code and module descriptor, including periodic throughput computation and metrics publication.",
      "most_likely_effort": 2.5
    },
    {
      "activity_id": "A3.3",
      "activity_name": "Unit test load receiving sink (U3)",
      "activity_description": "Write unit tests for counting, interval reporting, and metric formatting logic.",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "A3.4",
      "activity_name": "Integration test and document sink (U3)",
      "activity_description": "Verify the sink in an XD stream with the load generator, confirm reported throughput matches expectations, and write module documentation.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A4.1",
      "activity_name": "Configure Windows CI build jobs (U4)",
      "activity_description": "Create CI job definitions that build XD and execute runtime feature/functionality tests on Windows workers on a schedule.",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "A4.2",
      "activity_name": "Provision and experiment with Windows AMIs (U4)",
      "activity_description": "Create/iterate on Windows EC2 AMIs with the required toolchain (JDK, build tools) until the XD build and test environment is stable.",
      "most_likely_effort": 3.0
    },
    {
      "activity_id": "A4.3",
      "activity_name": "Triage and isolate failing Windows tests (U4)",
      "activity_description": "Run the Windows suites, analyze failures, isolate root causes (environment vs. product), and produce a categorized, documented failure list.",
      "most_likely_effort": 4.0
    },
    {
      "activity_id": "A4.4",
      "activity_name": "Stabilize pipeline and document known issues (U4)",
      "activity_description": "Harden the scheduled CI jobs (retry/quarantine handling where appropriate), document the Windows infrastructure and known failing tests.",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "A5.1",
      "activity_name": "Reproduce and analyze Kafka offset defect (U5)",
      "activity_description": "Reproduce the offset management problem in the Kafka source module and analyze the current consumer/offset handling code.",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "A5.2",
      "activity_name": "Implement offset management fix (U5)",
      "activity_description": "Implement explicit offset seek/commit handling so fetch operations can start efficiently from caller-specified offsets, preserving existing module options.",
      "most_likely_effort": 3.0
    },
    {
      "activity_id": "A5.3",
      "activity_name": "Test offset fix against Kafka (U5)",
      "activity_description": "Write unit and integration tests against a real Kafka broker covering fetch-from-offset, restart/resume, and edge cases (invalid/empty offsets).",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "A6.1",
      "activity_name": "Define benchmark plan (U6)",
      "activity_description": "Specify benchmark scenarios for a simple stream (payload sizes, rates, run durations) and the metrics to capture for throughput characterization.",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "A6.2",
      "activity_name": "Set up benchmark environment (U6)",
      "activity_description": "Provision the environment from the U1 AMI and deploy the simple stream using the U2 source and U3 sink over the Kafka bus.",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "A6.3",
      "activity_name": "Execute benchmark runs (U6)",
      "activity_description": "Run the benchmark matrix, repeat runs for consistency, and collect raw throughput and resource-utilization data.",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "A6.4",
      "activity_name": "Analyze and publish performance report (U6)",
      "activity_description": "Analyze results, characterize overall throughput, and write the performance report (also feeding the benchmarks page of U7).",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "A7.1",
      "activity_name": "Define gh-pages site structure (U7)",
      "activity_description": "Define the information architecture and navigation for samples, tutorials, links, performance benchmarks, and reference architectures.",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "A7.2",
      "activity_name": "Set up static site scaffolding (U7)",
      "activity_description": "Set up the Jekyll-based GitHub Pages site, theme, layout templates, and navigation skeleton.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A7.3",
      "activity_name": "Author site content (U7)",
      "activity_description": "Write and organize content pages: getting-started samples, tutorials, curated links, published benchmark results, and reference architecture descriptions.",
      "most_likely_effort": 4.0
    },
    {
      "activity_id": "A7.4",
      "activity_name": "Review and publish site (U7)",
      "activity_description": "Review content for accuracy, verify links and rendering, and publish the gh-pages site.",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "A8.1",
      "activity_name": "Research Lattice/Diego platform (U8)",
      "activity_description": "Study Lattice/Diego architecture, receptor API, and workload (LRP) model; stand up a small Lattice environment for experimentation.",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "A8.2",
      "activity_name": "Draft pluggable SPI design (U8)",
      "activity_description": "Draft the design for a pluggable deployment SPI in the XD runtime, including interfaces, lifecycle, and extension points.",
      "most_likely_effort": 3.0
    },
    {
      "activity_id": "A8.3",
      "activity_name": "Implement Lattice/Diego POC (U8)",
      "activity_description": "Implement a proof of concept that deploys XD runtime components onto Lattice/Diego and exercises basic stream deployment.",
      "most_likely_effort": 6.0
    },
    {
      "activity_id": "A8.4",
      "activity_name": "Evaluate POC and document findings (U8)",
      "activity_description": "Evaluate POC results, document scope, risks, and limitations, and finalize SPI design recommendations for the XD runtime.",
      "most_likely_effort": 3.0
    },
    {
      "activity_id": "A9.1",
      "activity_name": "Increment integration and regression verification",
      "activity_description": "Integrate all delivered changes, run the full regression suite (including the new Windows CI results), and stabilize the increment build.",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "A9.2",
      "activity_name": "Increment release notes and documentation rollup",
      "activity_description": "Prepare consolidated release notes covering new modules, the Kafka offset fix, CI changes, benchmark results, and the POC outcome.",
      "most_likely_effort": 1.0
    }
  ],
  "reported_total": {
    "most_likely_effort": 64.5
  }
}

